BEGIN READ ONLY; SET LOCAL statement_timeout='10s';
SELECT jsonb_build_object('captured_at',clock_timestamp(),'new_migration_history',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statements_md5',md5(array_to_string(statements,E'\n')),'statements_count',cardinality(statements)) ORDER BY version) FROM supabase_migrations.schema_migrations WHERE version IN ('20261007040000','20261007130000','20261008100000','20261008110000')),'required_rpcs',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_arguments(p.oid),'return',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'md5',md5(p.prosrc)) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('apply_import_chunk_v1','apply_progress_mutations_v1','apply_remove_mutations_v1','collection_series_children_v1','collection_series_page_v1','finish_library_import_v1','friend_activity_page_v1','home_bundle_v1','home_events_page_v1','home_pending_page_v1','import_job_status_v1','series_detail_bundle_v1','series_editions_page_v1','series_units_page_v1','start_library_import_v1','start_library_import_v2','prepare_import_chunk_v2','apply_import_chunk_v2','finish_library_import_v2','import_job_status_v2','import_jobs_page_v2','import_items_page_v2','cancel_library_import_v2','undo_library_import_chunk_v2','upsert_title_comment_scoped_v1','_apply_progress_mutations_for_user','_fence_set_progress_status','apply_import_session','undo_import_session')),'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('adaptation_coverage','artwork_materials','catalogue_units','detail_copy','home_publications','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','mapping_revision_spans','mapping_revisions','mutation_receipts','provider_entry_refs','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','theme_links','user_series_intent')),'home_flags',(SELECT jsonb_agg(jsonb_build_object('name',flag_name,'enabled',enabled,'rollout',rollout_percentage)) FROM public.feature_flags WHERE flag_name IN ('series_foundation_v1','series_home_native_v1','rag_assist_v1')),'deletion_helper_md5',(SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure('public._account_write_guard(text)'))) AS installed_backend; ROLLBACK;
